-- Hand-edited: before the unique index on lower(nickname) can be built, the case variants already
-- there must go (ADR-0069 decision 1 #57-6: 'Abc' keeps 'abc' out). The oldest account of each
-- variant keeps its nickname, and every later one gets a fresh auto nickname ('user_' + four of the
-- trigger's 32 characters, not taken in any case) — D4 lets existing data be reset, and every
-- account confirms its nickname in the onboarding anyway (nickname_confirmed_at is NULL for all).
-- A no-op on a database without variants.
DO $$
DECLARE
  alphabet CONSTANT text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  variant record;
  candidate text;
  i integer;
BEGIN
  FOR variant IN
    SELECT p.user_id
      FROM profiles p
     WHERE EXISTS (
       SELECT 1 FROM profiles q
        WHERE lower(q.nickname) = lower(p.nickname)
          AND (q.created_at, q.user_id) < (p.created_at, p.user_id)
     )
     ORDER BY p.created_at, p.user_id
  LOOP
    LOOP
      candidate := 'user_';
      FOR i IN 1..4 LOOP
        candidate := candidate || substr(alphabet, 1 + floor(random() * 32)::integer, 1);
      END LOOP;
      EXIT WHEN NOT EXISTS (SELECT 1 FROM profiles WHERE lower(nickname) = lower(candidate));
    END LOOP;
    UPDATE profiles SET nickname = candidate, updated_at = now() WHERE user_id = variant.user_id;
  END LOOP;
END
$$;--> statement-breakpoint
CREATE UNIQUE INDEX "profiles_nickname_lower_unique" ON "profiles" USING btree (lower("nickname"));--> statement-breakpoint
-- Hand-edited: a consent record is never rewritten (#57-5: the history is the record). buddha_app
-- keeps SELECT/INSERT/DELETE of the default privileges in docker/postgres/init/01-roles.sql and
-- loses UPDATE; DELETE stays for #184, which removes them once their retention period is over.
REVOKE UPDATE ON TABLE "consent_records" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: the one lock on a nickname, ignoring case, that everything taking or giving one up
-- holds until it commits — a change takes it on the nickname it gives up and on the one it takes
-- (in key order), the auto nickname's generator on each candidate — so a nickname cannot be taken
-- while another transaction is giving it up and recording its hold. The two-key form keeps it apart
-- from every single-key advisory lock (markets, admin roles), as the 본인확인's locks are.
CREATE FUNCTION lock_nickname(nickname text) RETURNS void
LANGUAGE sql AS $$
  SELECT pg_advisory_xact_lock(hashtext('buddha:nickname'), hashtext(lower(nickname)));
$$;--> statement-breakpoint
-- Hand-edited: whether `candidate` is held from `for_user` (#57-6, #37-16): another account — or no
-- account any more, a withdrawal's hold — gave it up less than 30 days ago (NICKNAME_HOLD_DAYS in
-- @buddha/shared), ignoring case. The account that gave it up is not held from it. Read under
-- lock_nickname(candidate) by whoever is about to take it.
CREATE FUNCTION nickname_held(candidate text, for_user text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT EXISTS (
    SELECT 1 FROM nickname_holds h
     WHERE lower(h.nickname) = lower(candidate)
       AND h.released_at > now() - interval '30 days'
       AND h.user_id IS DISTINCT FROM for_user
  );
$$;--> statement-breakpoint
-- Hand-edited: the auto nickname respects the holds (#57-6: a nickname given up is nobody else's
-- for 30 days, the generated one included). The function is re-created whole with 0031's body: the
-- profile with 'user_' + four characters (ADR-0052) and a zero balance, no grant, in the same
-- transaction as the user row (ADR-0019) — and now each candidate is locked (lock_nickname, as a
-- change locks it) and skipped while held; a taken one (in any case, the unique index on
-- lower(nickname)) is retried as before. Ten candidates at most, as before: 32^4 suffixes leave a
-- held or taken one a rare draw.
CREATE OR REPLACE FUNCTION create_profile_for_user() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  -- 32 unambiguous upper-case letters and digits (no 0/O/1/I): 32^4 = 1,048,576 suffixes.
  alphabet CONSTANT text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  candidate text;
  i integer;
  attempt integer := 0;
BEGIN
  LOOP
    attempt := attempt + 1;
    candidate := 'user_';
    FOR i IN 1..4 LOOP
      candidate := candidate || substr(alphabet, 1 + floor(random() * 32)::integer, 1);
    END LOOP;
    PERFORM lock_nickname(candidate);
    IF NOT nickname_held(candidate, NEW.id) THEN
      BEGIN
        INSERT INTO profiles (user_id, nickname) VALUES (NEW.id, candidate);
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        IF attempt >= 10 THEN RAISE; END IF;
      END;
    END IF;
    IF attempt >= 10 THEN
      RAISE EXCEPTION 'no free auto nickname for % after % candidates', NEW.id, attempt
        USING ERRCODE = 'unique_violation';
    END IF;
  END LOOP;
  INSERT INTO balances (user_id) VALUES (NEW.id);
  RETURN NEW;
END;
$$;
